const {config: CONFIG, questions: BUILTIN, assets: ASSETS, validationAssets} = window.MotionNoteData;
delete window.MotionNoteData;
const STORE='motionnote.study.v1', CUSTOM='motionnote.questions.v1';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nfmt=v=>Number(v||0).toLocaleString('ko-KR');
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const day=d=>new Date(d).toLocaleDateString('ko-KR',{month:'short',day:'numeric'});
const duration=ms=>{const s=Math.floor(Math.max(0,ms)/1000);return `${Math.floor(s/60)}분 ${s%60}초`;};
const time=ms=>{const s=Math.ceil(Math.max(0,ms)/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
const defaultState=()=>({version:1,exam:'health',records:{},bookmarks:[],notes:{},history:[],session:null,settings:{},preferences:{}});
let storageMessage='',state=defaultState(),custom={questions:[],pages:{}};
try{const raw=window.TrainerCloud?window.TrainerCloud.readState():JSON.parse(localStorage.getItem(STORE)||'null');if(raw){const s=raw;if(s.version!==1||!s.records||!Array.isArray(s.bookmarks)||!Array.isArray(s.history))throw Error('형식 오류');state={...defaultState(),...s};}const rawCustom=localStorage.getItem(CUSTOM);if(rawCustom)custom=Core.validateImport(JSON.parse(rawCustom),BUILTIN,CONFIG,validationAssets);}catch(e){storageMessage='저장 자료를 읽지 못했습니다. 기존 저장소는 그대로 두었습니다. 데이터 화면에서 확인 후 백업·초기화해 주세요.';state=defaultState();}
let BANK=[...BUILTIN,...custom.questions];Object.assign(ASSETS,custom.pages);let BYID=new Map(BANK.map(q=>[q.id,q]));
let view='home',listPage=1,listSearch='',listFilter='active',listDifficulty='all',historyId=null,reviewSession=null,reviewIndex=0,toastTimer,saveTimer,imageToken=0,dialogResolve=null;
let form={mode:'subject',subjects:[CONFIG[state.exam]?.subjects[0]||CONFIG.health.subjects[0]],year:'all',type:'official',count:20,difficulty:preferredDifficulty(state.exam)};
if(!CONFIG[state.exam])state.exam='health';
if(state.session&&(!Array.isArray(state.session.ids)||state.session.ids.some(id=>!BYID.has(id)))){state.session=null;storageMessage='이전 풀이의 문제 데이터를 찾을 수 없어 이어풀기를 불러오지 못했습니다.';}
function preferredDifficulty(exam){const value=state.preferences?.practiceDifficulty?.[exam];return ['all',...Core.difficultyLevels].includes(value)?value:'all';}
function activeDifficulty(){return form.mode==='mock'?'all':form.difficulty;}
function cfg(exam=state.exam){return {...CONFIG[exam],...(state.settings[exam]||{})};}
function save(){try{if(window.TrainerCloud)TrainerCloud.saveState(state);else localStorage.setItem(STORE,JSON.stringify(state));return true;}catch(e){storageMessage='이 브라우저에 저장할 수 없습니다. 데이터 관리에서 기록을 백업해 주세요. 저장 공간 또는 브라우저 설정을 확인하세요.';toast(storageMessage);return false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function modal(title,body,ok='확인',cancel='취소'){const d=$('#dialog');if(d.open){d.close();dialogResolve?.(false);}d.className='';$('#dialog-content').innerHTML=`<h2>${esc(title)}</h2><p>${esc(body)}</p><div class="dialog-actions"><button class="btn secondary" data-dialog="cancel">${esc(cancel)}</button><button class="btn" data-dialog="ok">${esc(ok)}</button></div>`;d.showModal();return new Promise(resolve=>{dialogResolve=resolve;});}
$('#dialog').addEventListener('click',e=>{const a=e.target.closest('[data-dialog]');if(a){$('#dialog').close();dialogResolve?.(a.dataset.dialog==='ok');dialogResolve=null;}});
$('#dialog').addEventListener('cancel',()=>{dialogResolve?.(false);dialogResolve=null;});
function badge(q){return q.type==='창작 예상문제'?'<span class="badge">창작 예상</span>':`<span class="badge">${esc(q.year)} 기출</span>${q.source.status==='preliminary'?'<span class="badge orange">가안 기준</span>':q.source.status==='missing'?'<span class="badge orange">정답 미확인</span>':'<span class="badge green">최종 정답</span>'}`;}
function stats(){const rows=Object.entries(state.records).filter(([id,r])=>r.exam===state.exam&&BYID.has(id));const attempts=rows.reduce((s,[,r])=>s+r.attempts,0),correct=rows.reduce((s,[,r])=>s+r.correct,0);return{unique:rows.length,attempts,correct,rate:attempts?Math.round(correct/attempts*100):null,wrong:rows.filter(([,r])=>r.wrong&&(!r.resolved||ReviewCore.isDue(r))).length,reviewed:rows.filter(([,r])=>r.wrong&&r.resolved&&!ReviewCore.isDue(r)).length,bookmarks:state.bookmarks.filter(id=>BYID.get(id)?.exam===state.exam).length};}
function updateNav(){const s=stats();$('#wrong-count').textContent=s.wrong;$('#bookmark-count').textContent=s.bookmarks;$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view||view==='result'&&b.dataset.nav==='history'||view==='study'&&b.dataset.nav==='home'));$('#breadcrumb').textContent=({home:'나의 학습실',wrong:'오답노트',bookmarks:'북마크',history:'학습 기록',guide:'시험 안내',data:'문제 데이터',study:'문제 풀기',result:'학습 결과',review:'정답과 해설'})[view]||'';}
function switchExam(exam){if(exam===state.exam)return;state.exam=exam;form={mode:'subject',subjects:[CONFIG[exam].subjects[0]],year:'all',type:'official',count:20,difficulty:preferredDifficulty(state.exam)};listPage=1;listSearch='';listDifficulty='all';resetWrongFilters();resetHistoryFilters();save();render();}
function navigate(to){flushTime();view=to;listPage=1;listSearch='';listFilter='active';listDifficulty='all';resetWrongFilters();if(to==='history')resetHistoryFilters();render();window.scrollTo({top:0});}
function examTabs(){return `<div class="exam-tabs" role="group" aria-label="시험 선택">${['health','sports'].map(ex=>`<button class="exam-tab ${state.exam===ex?'selected':''}" data-exam="${ex}" aria-pressed="${state.exam===ex}"><span class="exam-symbol">${ex==='health'?'✧':'↗'}</span><span><strong>${CONFIG[ex].name}</strong><small>${ex==='health'?'8과목 필수 · 160문항':'7과목 중 5과목 · 100문항'}</small></span><span class="checkmark">${state.exam===ex?'✓':''}</span></button>`).join('')}</div>`;}
function statCards(s){return `<div class="stats"><div class="stat"><div class="stat-label">풀어본 문제 <span>▤</span></div><div class="stat-value">${nfmt(s.unique)}<small>문항</small></div><div class="stat-foot">총 ${nfmt(s.attempts)}회 풀이 · 채점된 문제 기준</div></div><div class="stat"><div class="stat-label">누적 정답률 <span>◎</span></div><div class="stat-value">${s.rate??'—'}<small>${s.rate===null?'':'%'}</small></div><div class="stat-foot">${s.attempts?'반복 풀이를 포함한 전체 기록':'첫 문제를 풀면 기록이 시작돼요'}</div></div><div class="stat"><div class="stat-label">복습할 오답 <span>↺</span></div><div class="stat-value">${nfmt(s.wrong)}<small>문항</small></div><div class="stat-foot">복습 완료 ${nfmt(s.reviewed)}문항</div></div><div class="stat"><div class="stat-label">저장한 북마크 <span>☆</span></div><div class="stat-value">${nfmt(s.bookmarks)}<small>문항</small></div><div class="stat-foot">다시 보고 싶은 문제를 모아두세요</div></div></div>`;}
function pool(){return Core.questionPool(BANK,{exam:state.exam,year:form.year,type:form.type,difficulty:activeDifficulty()});}
function selectedPool(){return pool().filter(q=>form.subjects.includes(q.subject));}
function difficultyBadge(q){const level=Core.normalizeDifficulty(q.difficulty),color={하:'low',중:'medium',상:'high',미분류:'unknown'}[level];return `<span class="badge difficulty-badge ${color}" title="문제 내용에 따른 예상 난이도이며 공식 난이도나 이용자 정답률이 아닙니다.">${level==='미분류'?'난이도 미분류':'난이도 '+level}</span>`;}
function difficultyGuide(){return `<details class="difficulty-guide"><summary>난이도 분류 기준</summary><div><p><strong>하</strong> · 기본 개념 하나를 알고 직접 답할 수 있는 문제</p><p><strong>중</strong> · 관련 개념을 구별하거나 원리·공식을 한두 단계 적용하는 문제</p><p><strong>상</strong> · 여러 조건·개념·자료를 연결하여 판단하는 문제</p><p class="helper">사이트 자체 기준에 따른 운영자 평가(예상)입니다. AI가 문제 내용을 검토해 분류했으며 공식 출제기관이 정한 난이도나 이용자의 첫 풀이 정답률은 아닙니다. 지문 길이·그림 유무만으로 난이도를 정하지 않습니다. 개별 판단 근거는 정답·해설에서 확인할 수 있습니다.</p></div></details>`;}
function difficultyControls(){const counts=Core.difficultyCounts(Core.questionPool(BANK,{exam:state.exam,year:form.year,type:form.type,subjects:form.subjects})),total=Object.values(counts).reduce((a,b)=>a+b,0),selected=activeDifficulty();return `<fieldset class="difficulty-field"><legend>난이도 선택 <span>내용 기준 · 예상</span></legend><div class="difficulty-options" role="group" aria-label="학습 난이도">${['all','하','중','상',...(counts['미분류']||form.difficulty==='미분류'?['미분류']:[])].map(level=>`<button type="button" class="difficulty-option ${selected===level?'selected':''}" data-difficulty="${level}" aria-pressed="${selected===level}" ${form.mode==='mock'?'disabled':''}><strong>${level==='all'?'전체 난이도':level==='미분류'?'미분류':'난이도 '+level}</strong><span>${nfmt(level==='all'?total:counts[level])}문항</span></button>`).join('')}</div>${form.mode==='mock'?'<p class="helper">모의고사는 전체 난이도에서 출제합니다. 하·중·상을 골라 풀려면 과목별 연습 또는 무작위 연습을 선택하세요.</p>':'<p class="helper">선택한 과목·연도·문제 종류에 해당하는 문항 수입니다.</p>'}${difficultyGuide()}</fieldset>`;}
function collectionQuestions(kind=view){let rows=BANK.filter(q=>q.exam===state.exam&&(kind==='wrong'?state.records[q.id]?.wrong>0:state.bookmarks.includes(q.id)));if(kind==='wrong'&&listFilter!=='all')rows=rows.filter(q=>listFilter==='done'?state.records[q.id].resolved:!state.records[q.id].resolved);if(listSearch)rows=rows.filter(q=>[q.subject,q.stem,q.year,q.unit].join(' ').includes(listSearch));return Core.filterDifficulty(rows,listDifficulty);}
function updateSelection(){if($('#subject-help'))$('#subject-help').textContent=subjectHint();if($('#difficulty-picker'))$('#difficulty-picker').innerHTML=difficultyControls();if($('#pool-notice'))$('#pool-notice').innerHTML=poolNotice();if($('#selection-total'))$('#selection-total').textContent=nfmt(selectedPool().length);const start=$('[data-action="start"]');if(start)start.disabled=!selectedPool().length;}
function home(){const s=stats(),c=cfg(),official=BANK.filter(q=>q.exam===state.exam&&q.type==='공식 기출').length,samples=BANK.filter(q=>q.exam===state.exam&&q.type==='창작 예상문제').length;return `<section class="intro"><div><div class="eyebrow">YOUR DAILY STUDY, ONE STEP FORWARD</div><h1>오늘의 한 문제,<br class="hide"> 내일의 자신감.</h1><p>기출로 익히고, 오답으로 완성하는 나만의 학습 루틴.</p></div><div class="intro-art" aria-hidden="true"><i class="track"></i><i class="track"></i><i class="track"></i><i class="runner"></i></div></section>${examTabs()}${state.session?`<div class="note resume"><div><strong>진행 중인 ${esc(CONFIG[state.session.exam].short)} 학습이 있어요.</strong><p>${esc(state.session.label)} · ${Object.keys(state.session.answers).length}/${state.session.ids.length}문항 응답</p></div><button class="btn" data-action="resume">이어서 풀기 →</button></div>`:''}${statCards(s)}<div class="dashboard"><div><section class="card"><div class="card-head"><div><h2>나에게 맞는 학습 시작</h2><p class="subtext">기출 ${nfmt(official)}문항 · 창작 예시 ${nfmt(samples)}문항에서 오늘의 학습을 골라보세요.</p></div><span class="badge">문제은행</span></div><div class="step-label"><b>01</b> 학습 방식</div><div class="modes" role="group" aria-label="학습 방식">${[['subject','▤','과목별 연습'],['random','⤨','무작위 연습'],['mock','◷','모의고사']].map(([id,icon,label])=>`<button class="mode ${form.mode===id?'selected':''}" data-mode="${id}" aria-pressed="${form.mode===id}"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div><div class="step-label"><b>02</b> 과목 선택 <span class="helper" id="subject-help">${subjectHint()}</span></div><div class="subject-grid">${c.subjects.map(sub=>`<label class="subject-item"><input type="${form.mode==='subject'?'radio':'checkbox'}" name="subject" value="${esc(sub)}" ${form.subjects.includes(sub)?'checked':''} ${form.mode==='mock'&&state.exam==='health'?'disabled':''}><span>${esc(sub)}</span><small>${nfmt(pool().filter(q=>q.subject===sub).length)}문항</small></label>`).join('')}</div>${form.mode==='subject'?'':`<button class="text-button" data-action="select-all">${form.mode==='mock'&&state.exam==='sports'?'선택 초기화':'전체 선택 / 해제'}</button>`}<div class="field-row"><div class="field"><label for="year">출제 연도</label><select id="year"><option value="all">전체 연도</option>${c.years.map(y=>`<option value="${y}" ${form.year==y?'selected':''}>${y}년</option>`).join('')}</select></div><div class="field"><label for="qtype">문제 종류</label><select id="qtype">${[['official','공식 기출'],['sample','창작 예시'],['all','전체 문제']].map(([v,t])=>`<option value="${v}" ${v===form.type?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="count">문제 수</label><select id="count" ${form.mode==='mock'?'disabled':''}>${form.mode==='mock'?`<option value="auto">자동 구성</option>`:[5,10,20,40,50,80,160].map(n=>`<option value="${n}" ${form.count==n?'selected':''}>${n}문항</option>`).join('')}</select></div></div><div id="difficulty-picker">${difficultyControls()}</div><div id="pool-notice">${poolNotice()}</div><div class="start-row"><p><strong id="selection-total">${nfmt(selectedPool().length)}</strong>문항 선택 가능<br>한 번의 학습이 쌓여 실력이 됩니다.</p><button class="btn" data-action="start" ${selectedPool().length?'':'disabled'}>학습 시작</button></div></section><section class="card recent"><div class="card-head"><h2>최근 학습</h2><button class="text-button" data-nav="history">전체 보기 ↗</button></div>${recentHistory(3)}</section></div><aside class="right-stack"><section class="card review-card"><div class="review-icon">↺</div><h2>한 번 더 풀면,<br>내 것이 되는 문제.</h2><p class="subtext">틀린 문제는 다음 학습의 출발점이에요.</p><div class="review-total">${s.wrong}<small>문항 복습 대기</small></div><button class="btn full" data-nav="wrong">오답노트 열기 <span>→</span></button></section><section class="card mini-guide"><h3>시험 한눈에 보기</h3><div class="guide-row"><span>시험 과목</span><strong>${state.exam==='health'?'8과목 필수':'7과목 중 5과목'}</strong></div><div class="guide-row"><span>시험시간</span><strong>${state.exam==='health'?c.minutes.join(' + ')+'분':c.minutes[0]+'분'}</strong></div><div class="guide-row"><span>합격 기준</span><strong>과목 ${c.passSubject} · 평균 ${c.passTotal}점</strong></div><p class="helper">공식 안내 확인 · ${CONFIG.verifiedAt}<br>첨부 기출과 창작 예시를 구분해 제공합니다.</p><button class="text-button" data-nav="guide">시험 안내 자세히 ↗</button></section></aside></div>`;}
function subjectHint(){return form.mode==='subject'?'한 과목을 선택하세요':form.mode==='mock'?(state.exam==='health'?'8과목 전체 응시':`${form.subjects.length} / 5과목 선택`):`${form.subjects.length}과목 선택`;}
function poolNotice(){const p=selectedPool();if(!p.length)return '<p class="note warning">선택한 조건의 문제가 없습니다. 과목·연도·문제 종류 또는 난이도를 바꿔 주세요.</p>';const known=p.filter(Core.known);let html='';if(form.mode!=='mock'&&p.length<form.count)html+=`<p class="note">선택한 난이도·과목의 ${p.length}문항을 모두 출제합니다. 부족한 문항을 중복으로 채우지 않습니다.</p>`;if(p.some(q=>q.source.status==='preliminary'))html+='<p class="helper section-gap">ⓘ 일부 기출은 첨부된 정답 가안으로 채점합니다. 최종 정답과 다를 수 있습니다.</p>';if(p.some(q=>!Core.known(q)))html+='<p class="note warning">정답표가 없는 문항은 채점과 정답률 집계에서 제외되며 모의고사에는 출제되지 않습니다.</p>';if(form.mode==='mock'){const full=form.subjects.length===cfg().selectCount&&form.subjects.every(s=>known.filter(q=>q.subject===s).length>=cfg().perSubject);html+=`<p class="note">${full?`정규 구성 모의고사 · ${cfg().selectCount*cfg().perSubject}문항`:'축소 체험 모의고사 · 부족한 문항을 중복 출제하지 않습니다.'}${state.exam==='health'?'<br>1교시 제출 → 휴식 → 2교시 → 전체 채점':''}</p>`;}return html;}
function empty(title,description,action=''){return `<div class="empty"><div class="empty-symbol">▧</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function recentHistory(limit){const h=HistoryCore.rows(state.history,{exam:state.exam}).slice(0,limit);return h.length?h.map(h=>`<div class="list-item"><div class="list-main"><div class="meta"><span>${day(h.finishedAt)}</span><span>·</span><span>${esc(h.label)}</span></div><h3>${h.summary.correct}/${h.summary.gradeable} 정답 <span class="badge">${h.summary.rate===null?'채점 제외':h.summary.rate+'%'}</span></h3><p>${duration(h.elapsedMs)} · ${h.ids.length}문항</p></div><button class="btn secondary" data-result="${esc(h.id)}">결과 보기</button></div>`).join(''):empty('아직 학습 기록이 없어요','첫 문제를 풀고 나만의 학습 기록을 만들어보세요.');}
function render(){updateNav();$('#main').innerHTML=(storageMessage?`<p class="note warning" role="alert">${esc(storageMessage)}</p>`:'')+({home,wrong:wrongNotebook,bookmarks:()=>collection('bookmarks'),history:historyPage,guide:guidePage,data:dataPage,study:studyPage,result:resultPage,review:()=>reviewOrigin==='wrong'?wrongAnalysisPage():reviewPage()}[view]||home)();if(view==='study'||view==='review')drawCurrentImage();if(view==='wrong')updateWrongSelection();$('#top-date').textContent=new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit'});}
async function begin(ids,mode,label,full=false){if(!ids.length){toast('조건에 맞는 문제가 없습니다.');return;}if(state.session){if(!await modal('진행 중인 학습을 마칠까요?','새 학습을 시작하면 이어풀기는 종료됩니다. 이미 확인한 문제의 학습 기록은 유지됩니다.','새 학습 시작'))return;}
 const c=cfg(),questions=ids.map(id=>BYID.get(id)),now=Date.now();let groups=[ids];if(mode==='mock'&&state.exam==='health'){groups=[ids.filter(id=>c.subjects.slice(0,4).includes(BYID.get(id).subject)),ids.filter(id=>c.subjects.slice(4).includes(BYID.get(id).subject))].filter(g=>g.length);}
 const budgets=mode==='mock'?groups.map((g,i)=>full?c.minutes[i]*60000:Math.max(60000,Math.round(g.length/(state.exam==='health'?4*c.perSubject:5*c.perSubject)*c.minutes[Math.min(i,c.minutes.length-1)]*60000))):[];
 state.session={id:uid(),exam:state.exam,rules:structuredClone(c),mode,label,ids,groups,budgets,full,phase:0,stage:'quiz',index:0,answers:{},checked:{},graded:{},flags:[],startedAt:now,phaseStartedAt:now,deadline:mode==='mock'?now+budgets[0]:null,elapsedMs:0,lastTick:now};view='study';save();render();window.scrollTo({top:0});}
function startFromForm(){if(!form.subjects.length){toast('학습할 과목을 선택해 주세요.');return;}if(form.mode==='mock'&&form.subjects.length!==cfg().selectCount){toast(`모의고사는 ${cfg().selectCount}과목을 선택해야 합니다.`);return;}let p=selectedPool(),label=form.mode==='subject'?'과목별 연습':'무작위 연습',full=false;if(form.mode==='mock'){p=Core.mockQuestions(p,cfg().subjects.filter(s=>form.subjects.includes(s)),cfg().perSubject);full=p.length===cfg().selectCount*cfg().perSubject;label=full?'정규 구성 모의고사':'축소 체험 모의고사';}else if(form.mode==='random')p=Core.shuffle(p).slice(0,form.count);else p=p.slice().sort((a,b)=>(b.year||0)-(a.year||0)||(a.number-b.number)).slice(0,form.count);if(form.mode!=='mock'&&activeDifficulty()!=='all')label+=' · 난이도 '+activeDifficulty();begin(p.map(q=>q.id),form.mode,label,full);}
function sessionQuestions(s){return s.ids.map(id=>BYID.get(id)).filter(Boolean);}
function range(s){const g=s.groups?.[s.phase]||s.ids;return [s.ids.indexOf(g[0]),s.ids.indexOf(g[g.length-1])];}
function flushTime(){const s=state.session;if(!s)return;const now=Date.now();if(s.stage==='quiz'&&view==='study'&&!document.hidden){s.questionTimes??={};const qid=s.ids[s.index];s.questionTimes[qid]=(s.questionTimes[qid]||0)+Math.max(0,Math.min(now-(s.lastTick||now),5000));}if(s.stage==='quiz'&&s.mode!=='mock'&&view==='study'&&!document.hidden)s.elapsedMs+=Math.max(0,Math.min(now-(s.lastTick||now),5000));s.lastTick=now;}
function elapsed(s){if(s.mode==='mock')return (s.elapsedMs||0)+(s.stage==='quiz'?Math.max(0,Math.min(Date.now(),s.deadline)-s.phaseStartedAt):0);return s.elapsedMs||0;}
function studyPage(){const s=state.session;if(!s){view='home';return home();}if(s.stage==='break'){return `<div class="section-title"><div><div class="eyebrow">TAKE A BREATH</div><h1>1교시를 마쳤습니다.</h1><p>제출한 답안은 잠겨 있으며, 정답은 2교시가 끝난 뒤 공개됩니다.</p></div></div><section class="card"><h2>잠시 쉬어가세요</h2><p class="subtext">공식 휴식시간 ${s.rules?.breakMinutes??20}분 · 학습에서는 바로 다음 교시로 넘어갈 수 있습니다.</p><div class="timer section-gap" id="break-timer">${time(s.breakDeadline-Date.now())}</div><div class="data-actions"><button class="btn" data-action="skip-break">휴식 건너뛰고 2교시 시작 →</button><button class="btn secondary" data-nav="home">학습실로</button></div></section>`;}
 const q=BYID.get(s.ids[s.index]),[lo,hi]=range(s),checked=!!s.checked[q.id]&&s.mode!=='mock';return `<div class="study-head"><div class="study-title"><div class="eyebrow">${esc(s.label)}</div><h1>${esc(CONFIG[s.exam].short)}</h1><div class="meta">${s.mode==='mock'&&s.exam==='health'?`${s.phase+1}교시 · `:''}${esc(q.subject)}</div></div><div class="timer"><small>${s.mode==='mock'?'남은 시간':'학습 시간'}</small><span id="session-timer">${time(s.mode==='mock'?s.deadline-Date.now():elapsed(s))}</span></div></div><div class="study-layout"><section class="card question-card"><div class="progress-line"><span>${s.index+1} / ${s.ids.length}문항</span><span>${Object.keys(s.answers).length}문항 응답</span></div><div class="progress"><span style="width:${Object.keys(s.answers).length/s.ids.length*100}%"></span></div>${questionBody(q,s,checked)}<div class="question-actions"><button class="text-button" data-action="flag">${s.flags.includes(q.id)?'✓ 나중에 풀기로 표시됨':'⚑ 나중에 풀기'}</button>${s.mode==='mock'?'<span class="helper">제출 후 정답과 해설이 공개됩니다.</span>':`<button class="btn" data-action="check" ${!s.answers[q.id]||checked?'disabled':''}>${checked?'정답·해설 확인 완료 ✓':'정답·해설 확인'}</button>`}</div>${checked?explanation(q,s):''}<div class="study-footer"><button class="btn secondary" data-action="prev" ${s.index<=lo?'disabled':''}>← 이전 문제</button><button class="btn ${s.index>=hi?'secondary':''}" data-action="next" ${s.index>=hi?'disabled':''}>다음 문제 →</button></div><p class="key-hint"><kbd>1</kbd>–<kbd>4</kbd> 답 선택 · <kbd>←</kbd><kbd>→</kbd> 문제 이동 · <kbd>B</kbd> 북마크</p></section><aside class="card navigator"><div class="card-head"><h3>문제 둘러보기</h3><span class="badge">${hi-lo+1}문항</span></div><div class="number-grid">${s.ids.slice(lo,hi+1).map((id,i)=>`<button data-jump="${lo+i}" class="${lo+i===s.index?'current':''} ${s.answers[id]?'answered':''} ${s.flags.includes(id)?'flagged':''}" aria-label="${lo+i+1}번 문제${s.answers[id]?', 응답함':''}">${lo+i+1}</button>`).join('')}</div><div class="nav-legend"><span></span> 응답한 문제　 ⚑ 나중에 풀기<br>${s.mode==='mock'?'교시가 끝나면 답안을 바꿀 수 없습니다.':'확인한 정답은 자동으로 기록됩니다.'}</div><button class="btn full" data-action="submit">${s.mode==='mock'&&s.phase<s.groups.length-1?'1교시 제출':'학습 완료 및 채점'}</button><button class="text-button" data-nav="home">학습실로 돌아가기</button></aside></div>`;}
function questionBody(q,s,reveal){const answer=s.answers[q.id],correct=Core.known(q),book=state.bookmarks.includes(q.id);return `<div class="question-top"><div class="meta">${badge(q)}${difficultyBadge(q)}<span>${esc(q.subject)} · ${q.year?`${q.number}번`:esc(q.unit)}</span></div><button class="bookmark-toggle ${book?'saved':''}" data-bookmark="${esc(q.id)}" aria-pressed="${book}" aria-label="${book?'북마크 해제':'북마크 저장'}">${book?'★':'☆'}</button></div>${q.pageId?`<div class="image-tools"><span>원문 ${q.number}번 · <button class="text-button" data-action="zoom-out" aria-label="원문 글자 축소">−</button> <span id="zoom-value">${state.preferences.zoom||100}%</span> <button class="text-button" data-action="zoom-in" aria-label="원문 글자 확대">＋</button></span><button class="text-button" data-original="${esc(q.pageId)}">전체 페이지 확대 ↗</button></div><div class="original-wrap" tabindex="0" aria-label="원문 문제 이미지. 확대 후 좌우로 스크롤할 수 있습니다."><canvas id="question-canvas" role="img" aria-label="${esc(q.year+'년 '+q.subject+' '+q.number+'번 원문. 전체 페이지 확대 버튼으로 확대할 수 있습니다.')}" data-page="${esc(q.pageId)}" data-crop="${esc(JSON.stringify(q.crop))}"></canvas></div>`:`<h2 class="question-title">${esc(q.stem)}</h2><p class="helper" style="margin-bottom:15px">학습용 창작 예상문제이며 실제 기출문제가 아닙니다</p>`}<div class="choices ${q.pageId?'original-choices':''}" role="radiogroup" aria-label="정답 선택">${q.choices.map((t,i)=>{const n=i+1,cls=reveal&&correct?(q.answer.includes(n)?'correct':answer===n?'incorrect':''):answer===n?'selected':'';return `<button class="choice ${cls}" data-choice="${n}" role="radio" aria-checked="${answer===n}" ${reveal?'disabled':''}><span class="num">${n}</span><span class="label">${q.pageId?'번':esc(t)}</span>${reveal&&correct&&q.answer.includes(n)?'<span class="result-icon">✓ 정답</span>':reveal&&answer===n&&correct?'<span class="result-icon">✕ 내 답</span>':''}</button>`;}).join('')}</div>`;}
function explanation(q,s,includeReflection=true){
 window.TrainerCloud?.markSeen([q.id]);
 const a=s.answers[q.id],known=Core.known(q),ok=known&&Core.correct(q,a),e=ExplanationLibrary.get(q);
 const authored=e.kind==='authored',sample=q.type==='창작 예상문제',hasText=!e.loading&&!e.loadError&&e.choices?.length===4;
 const lines=value=>esc(value).replace(/\n/g,'<br>');
 const correctChoices=sample&&known?`<div class="sample-correct-choices">${q.answer.map(n=>`<p class="sample-correct-choice"><span>정답 ${n}번</span><strong>${lines(q.choices[n-1])}</strong></p>`).join('')}</div>`:'';
 let body='';
 if(e.loading)body='<div class="explanation-loading" role="status">해설을 불러오고 있습니다…</div>';
 else if(e.loadError)body='<p class="note warning" role="alert">해설을 불러오지 못했습니다. 인터넷 연결을 확인하고 다시 시도해 주세요.</p><button class="btn secondary" data-action="retry-explanation">해설 다시 불러오기</button>';
 else body=`${e.status==='needs_review'?'<p class="note warning">ⓘ 추가 검토가 필요한 문항입니다. 아래 확인 사항을 참고해 주세요.</p>':''}<div class="explanation-section ${sample?'sample-answer-explanation':''}"><h3 ${sample?'id="sample-answer-title" tabindex="-1"':''}>${e.status==='needs_review'?'확인이 필요한 내용':sample?'정답 해설':'정답의 근거'}</h3>${correctChoices}<p>${lines(e.summary)}</p></div>${!known&&e.suggestedAnswer?`<p class="note warning">학습용 해설의 추정 정답: ${e.suggestedAnswer.join(', ')}번<br>공식 정답표가 없어 채점에는 반영하지 않습니다.</p>`:''}${hasText?`<div class="explanation-section"><h3>선택지별 해설</h3><div class="explanation-options">${e.choices.map((text,i)=>`<div class="option-explain ${known&&q.answer.includes(i+1)?'answer-option':''}"><div class="option-explain-head"><strong>${i+1}번</strong>${known&&q.answer.includes(i+1)?'<span>✓ 정답 선택지</span>':a===i+1?'<span>내가 선택한 답</span>':''}</div><p>${lines(text)}</p></div>`).join('')}</div></div>`:''}${e.keyPoint?`<div class="explanation-key"><strong>기억할 핵심</strong><p>${lines(e.keyPoint)}</p></div>`:''}${e.references?.length?`<details class="explanation-references"><summary>해설 참고 자료 ${e.references.length}개</summary><ul>${e.references.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a></li>`).join('')}</ul></details>`:''}`;
 return `<section class="explanation" aria-label="정답과 해설"><div class="answer-verdict ${!known?'unknown':ok?'':'wrong'}">${!known?'ⓘ 정답 미확인 · 채점 제외':ok?'✓ 정답입니다':a?'✕ 다시 확인해 보세요':view==='review'&&reviewOrigin==='wrong'?'— 이전 선택 답안 기록 없음':'— 응답하지 않은 문제'}${known?` <span class="badge">정답 ${q.answer.join(', ')}번</span>`:''}</div>${q.source.status==='preliminary'?'<div class="note warning">첨부 정답 가안 기준입니다. 최종 정답 확정 여부는 공식 자료와 대조해 주세요.</div>':''}<div class="explanation-heading"><h2>문제 해설</h2><span class="badge">${authored?'학습용 작성 해설':q.type==='창작 예상문제'?'창작 예시 해설':'해설 안내'}</span></div>${authored?'<p class="explanation-provenance">공식 해설이 아닌 AI 작성 초안입니다. 참고 자료와 함께 확인해 주세요.</p>':''}${body}${q.difficultyReview?`<details class="difficulty-reason"><summary>난이도 평가 근거 · ${esc(Core.normalizeDifficulty(q.difficulty))}</summary><p>${esc(q.difficultyReview.reason)}</p><p class="helper">${q.questionTypes?.length?'문제 유형: '+esc(q.questionTypes.join(' · '))+'<br>':''}내용 검토에 따른 예상 난이도 · ${esc(q.difficultyReview.reviewedAt)}<br>공식 난이도나 실제 정답률을 뜻하지 않습니다.</p></details>`:''}${known&&q.answer.length>1?'<p class="note">복수 인정 정답입니다. 표시된 번호 중 하나를 고르면 정답으로 처리합니다.</p>':''}<details class="source-detail"><summary>문제·정답 출처</summary><p>${esc(q.source.file)}${q.source.page?` · PDF ${q.source.page}쪽`:''}${q.source.answerFile?`<br>정답표: ${esc(q.source.answerFile)}`:''}${q.source.note?`<br>${esc(q.source.note)}`:''}</p></details>${!includeReflection?'':(state.records[q.id]?.wrong>0||ReviewCore.hasTemplate(state.notes[q.id]))?reflectionEditor(q,s,e):`<details><summary>나만의 학습 메모 <span class="saved-indicator" id="note-save-status"></span></summary><label class="helper" for="question-note">헷갈린 개념이나 확인한 해설을 적어두세요.</label><textarea id="question-note" class="note-input" data-note="${esc(q.id)}" placeholder="이 문제에서 기억할 내용">${esc(state.notes[q.id]||'')}</textarea></details>`}</section>`;
}

function drawCurrentImage(){const canvas=$('#question-canvas');if(!canvas)return;canvas.style.width=(state.preferences.zoom||100)+'%';canvas.style.maxWidth='none';const token=++imageToken,img=new Image(),crop=JSON.parse(canvas.dataset.crop);img.onload=()=>{if(token!==imageToken||!canvas.isConnected)return;const [x0,y0,x1,y1]=crop;canvas.width=Math.max(1,Math.round(img.width*(x1-x0)));canvas.height=Math.max(1,Math.round(img.height*(y1-y0)));canvas.getContext('2d').drawImage(img,img.width*x0,img.height*y0,canvas.width,canvas.height,0,0,canvas.width,canvas.height);};img.onerror=()=>{if(token!==imageToken||!canvas.isConnected)return;const box=canvas.parentNode;box.innerHTML='<p class="note warning" role="alert">원문 이미지를 불러오지 못했습니다. 인터넷 연결을 확인한 뒤 다시 시도해 주세요.</p><button class="btn secondary" data-action="retry-image">이미지 다시 불러오기</button>';};img.src=ASSETS[canvas.dataset.page]||'';}
let cloudAction=false;
function choose(n){if(cloudAction)return;const s=state.session;if(view!=='study'||!s||s.stage!=='quiz')return;const id=s.ids[s.index];if(s.checked[id]&&s.mode!=='mock')return;s.answers[id]=n;save();render();}
async function checkAnswer(){if(cloudAction)return;const s=state.session;if(!s||s.mode==='mock')return;const q=BYID.get(s.ids[s.index]);if(!s.answers[q.id]||s.checked[q.id])return;cloudAction=true;flushTime();try{await window.TrainerCloud?.submitAnswers(s,[q.id],true);}catch(e){toast(e.message);}finally{cloudAction=false;}if(state.session?.id!==s.id)return;s.checked[q.id]=true;Core.gradeRecord(state,s,q,Date.now());save();render();if(q.type==='창작 예상문제'){const heading=$('#sample-answer-title');if(heading){heading.focus({preventScroll:true});heading.closest('.explanation').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}}}
function jump(i){if(cloudAction)return;flushTime();const s=state.session;if(!s||s.stage!=='quiz')return;const [lo,hi]=range(s);s.index=Math.max(lo,Math.min(hi,i));save();render();}
function toggleBookmark(id){const i=state.bookmarks.indexOf(id);if(i<0)state.bookmarks.push(id);else state.bookmarks.splice(i,1);save();render();toast(i<0?'북마크에 저장했습니다.':'북마크를 해제했습니다.');}
async function submit(auto=false){if(cloudAction)return;const s=state.session;if(!s||s.stage!=='quiz')return;const stageIds=s.mode==='mock'?s.groups[s.phase]:s.ids,missing=stageIds.filter(id=>!s.answers[id]).length;
 if(!auto&&!await modal(s.mode==='mock'&&s.phase<s.groups.length-1?'1교시를 제출할까요?':'학습을 마칠까요?',`${missing?`미응답 문제가 ${missing}개 있습니다.\n`:''}${s.mode==='mock'?'제출 후에는 해당 답안을 수정할 수 없습니다.':'응답한 문제는 채점하고 학습 기록에 저장합니다.'}`,'제출 및 계속'))return;
 if(cloudAction||!state.session||state.session.id!==s.id||s.stage!=='quiz')return;
 cloudAction=true;flushTime();try{await window.TrainerCloud?.submitAnswers(s,stageIds,s.mode!=='mock');}catch(e){toast(e.message);}finally{cloudAction=false;}if(state.session?.id!==s.id)return;
 if(s.mode==='mock'){s.elapsedMs+=Math.max(0,Math.min(Date.now(),s.deadline)-s.phaseStartedAt);s.phaseStartedAt=Date.now();}
 if(s.mode==='mock'&&s.phase<s.groups.length-1){s.stage='break';s.breakDeadline=Date.now()+(s.rules?.breakMinutes??20)*60000;save();render();if(auto)toast('1교시 시간이 종료되어 답안을 제출했습니다.');return;}
 for(const q of sessionQuestions(s)){Core.gradeRecord(state,s,q,Date.now());s.checked[q.id]=true;}
 const summary=Core.summarize(sessionQuestions(s),s.answers,s.serverVerdicts),h={id:s.id,exam:s.exam,mode:s.mode,label:s.label,full:s.full,rules:s.rules,ids:s.ids,answers:s.answers,serverVerdicts:s.serverVerdicts,summary,elapsedMs:s.elapsedMs,startedAt:s.startedAt,finishedAt:Date.now()};state.history.push(h);state.exam=h.exam;state.session=null;historyId=h.id;view='result';save();render();window.scrollTo({top:0});if(auto)toast('시험시간이 종료되어 자동으로 채점했습니다.');}
function nextPhase(){if(cloudAction)return;const s=state.session;if(!s||s.stage!=='break')return;state.exam=s.exam;view='study';const now=Date.now();s.phase++;s.stage='quiz';s.index=s.ids.indexOf(s.groups[s.phase][0]);s.phaseStartedAt=now;s.deadline=Math.min(now,s.breakDeadline||now)+s.budgets[s.phase];s.lastTick=now;save();render();}
function collection(kind){const s=stats(),title=kind==='wrong'?'오답노트':'북마크';const items=collectionQuestions(kind);const total=items.length,shown=items.slice((listPage-1)*15,listPage*15);return `<div class="section-title"><div><div class="eyebrow">${kind==='wrong'?'LEARN FROM EVERY MISTAKE':'KEEP WHAT MATTERS'}</div><h1>${title}</h1><p>${kind==='wrong'?'틀렸던 기록은 남기고, 다시 맞힌 문제는 복습 완료로 표시합니다.':'다시 살펴볼 문제를 모아, 필요할 때 바로 꺼내보세요.'}</p></div><button class="btn" data-action="review-collection" ${total?'':'disabled'}>모아서 풀기 →</button></div>${examTabs()}<div class="toolbar"><input id="list-search" value="${esc(listSearch)}" placeholder="과목, 연도, 문제 검색" aria-label="문제 검색">${kind==='wrong'?`<select id="list-filter" aria-label="복습 상태"><option value="active" ${listFilter==='active'?'selected':''}>복습 대기 ${s.wrong}</option><option value="done" ${listFilter==='done'?'selected':''}>복습 완료 ${s.reviewed}</option><option value="all" ${listFilter==='all'?'selected':''}>전체 오답 이력</option></select>`:''}<select id="list-difficulty" aria-label="복습 난이도">${['all',...Core.difficultyLevels].map(level=>`<option value="${level}" ${level===listDifficulty?'selected':''}>${level==='all'?'전체 난이도':'난이도 '+level}</option>`).join('')}</select><span class="helper">${nfmt(total)}문항</span></div><section class="card">${shown.length?shown.map(q=>{const r=state.records[q.id];return `<div class="list-item"><div class="list-main"><div class="meta">${badge(q)}${difficultyBadge(q)}<span>${esc(q.subject)}</span>${kind==='wrong'?`<span class="badge ${r.resolved?'green':'orange'}">${r.resolved?'✓ 복습 완료':'↺ 복습 대기'}</span>`:''}</div><h3>${esc(q.year?`${q.year}년 ${q.subject} ${q.number}번`:q.stem)}</h3><p>${r?`누적 ${r.attempts}회 풀이 · ${r.wrong}회 오답 · 최근 ${day(r.lastAt)}`:'아직 풀지 않은 문제'}</p></div><button class="btn secondary" data-practice-id="${esc(q.id)}">다시 풀기</button>${kind==='bookmarks'?`<button class="bookmark-toggle saved" data-bookmark="${esc(q.id)}" aria-label="북마크 해제">★</button>`:''}</div>`;}).join(''):empty(listDifficulty!=='all'||listSearch?'선택한 조건의 문제가 없어요':kind==='wrong'?'아직 복습할 문제가 없어요':'아직 저장한 문제가 없어요',listDifficulty!=='all'||listSearch?'난이도를 전체로 바꾸거나 검색 조건을 조정해 주세요.':kind==='wrong'?'문제를 풀면서 틀린 문항이 이곳에 쌓입니다.':'문제 화면의 별을 눌러 북마크해 보세요.',`<button class="btn secondary" data-nav="home">학습 시작하기 →</button>`)}${total>15?`<div class="pagination"><button class="btn secondary" data-page="${listPage-1}" ${listPage===1?'disabled':''}>이전</button><span>${listPage} / ${Math.ceil(total/15)}</span><button class="btn secondary" data-page="${listPage+1}" ${listPage*15>=total?'disabled':''}>다음</button></div>`:''}</section>`;}
function collectionIds(){return collectionQuestions().map(q=>q.id);}
function bars(subjects){return `<div class="subject-bars">${Object.entries(subjects).map(([sub,r])=>{const total=r.gradeable??r.attempts,rate=total?Math.round(r.correct/total*100):0;return `<div><div class="bar-header"><span>${esc(sub)}</span><span>${total?rate+'%':'—'} <small class="helper">(${r.correct}/${total||0})</small></span></div><div class="bar ${total&&rate<60?'weak':''}"><span style="width:${rate}%"></span></div></div>`;}).join('')}</div>`;}
function historyPage(){return renderHistory();}
function currentResult(){return state.history.find(h=>h.id===historyId)||state.history.at(-1);}
function resultPage(){const h=currentResult();if(!h)return empty('결과를 찾을 수 없습니다','학습을 완료해 주세요.');const s=h.summary,c=h.rules||cfg(h.exam),subjectScores=Object.values(s.subjects).map(x=>x.gradeable?x.correct/x.gradeable*100:0),canPass=h.mode==='mock'&&h.full&&s.gradeable===c.selectCount*c.perSubject,pass=canPass&&s.correct/s.gradeable*100>=c.passTotal&&subjectScores.every(n=>n>=c.passSubject),preliminary=h.ids.some(id=>BYID.get(id)?.source.status==='preliminary');return `<button class="hl-back" data-history-back>학습 기록으로</button><div class="section-title"><div><div class="eyebrow">SESSION COMPLETE</div><h1>오늘도 한 걸음 나아갔어요.</h1><p>${esc(CONFIG[h.exam].short)} · ${esc(h.label)} · ${day(h.finishedAt)}</p></div></div><section class="score-banner"><div><h2>${canPass?(pass?'✓ 합격 기준 충족':'다시 도전해 보세요'):'학습을 완료했습니다'}</h2><p>${canPass?`과목별 ${c.passSubject}점 · 전체 ${c.passTotal}점 기준 ${pass?'충족':'미달'}`:'틀린 이유를 확인하고, 한 번 더 풀어보세요.'}<br>${duration(h.elapsedMs)} 동안 ${s.total}문항 학습</p></div><div class="score-circle">${s.rate??'—'}${s.rate===null?'':'%'}<small>정답률 · 미응답 포함</small></div></section>${preliminary?'<p class="note warning">정답 가안이 포함된 채점 결과입니다. 최종 정답으로 재확인하기 전까지 참고용으로 이용하세요.</p>':''}${wrongResultSummary(h)}${h.mode==='mock'&&!h.full?'<p class="note">축소 체험 모의고사입니다. 공식 문항 수보다 적으므로 합격 여부를 판정하지 않습니다.</p>':''}<div class="stats">${[['✓ 정답',s.correct,'정답으로 확인한 문제'],['✕ 오답',s.wrong,'오답노트에 자동 저장'],['— 미응답',s.unanswered,'선택하지 않은 문제'],['ⓘ 채점 제외',s.ungraded,'응답했으나 정답 미확인']].map(([label,n,desc])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${n}<small>문항</small></div><div class="stat-foot">${desc}</div></div>`).join('')}</div><div class="two-cols"><section class="card"><div class="card-head"><h2>과목별 결과</h2><span class="helper">채점 가능 ${s.gradeable}문항</span></div>${bars(s.subjects)}</section><section class="card"><h2>기억에 남기는 한 번의 복습</h2><p class="subtext">정답과 해설을 살펴보고, 어려웠던 문제를 다시 만나보세요.</p><div class="data-actions"><button class="btn full" data-action="review-result">전체 문제·해설 보기 →</button><button class="btn secondary full" data-action="retry-wrong" ${s.wrong?'':'disabled'}>틀린 ${s.wrong}문항 다시 풀기</button><button class="btn secondary full" data-nav="home">학습실로 돌아가기</button></div>${s.unanswered?'<p class="helper">미응답 문제는 오답노트에 저장되지 않습니다. 전체 문제 보기에서 확인하세요.</p>':''}</section></div>`;}
function reviewPage(){const s=reviewSession;if(!s||!s.ids.length)return empty('검토할 문제가 없습니다','학습 기록에서 결과를 선택해 주세요.');const q=BYID.get(s.ids[reviewIndex]);return `<div class="study-head"><div><div class="eyebrow">REVIEW & REMEMBER</div><h1>정답과 해설</h1><p class="subtext">${reviewIndex+1} / ${s.ids.length} · ${esc(q.subject)}</p></div><button class="btn secondary" data-action="back-result">결과로 돌아가기</button></div><section class="card question-card">${questionBody(q,s,true)}${explanation(q,s)}<div class="study-footer"><button class="btn secondary" data-review-jump="${reviewIndex-1}" ${reviewIndex===0?'disabled':''}>← 이전 문제</button><button class="btn" data-review-jump="${reviewIndex+1}" ${reviewIndex===s.ids.length-1?'disabled':''}>다음 문제 →</button></div></section><section class="card section-gap"><h3>전체 문제</h3><div class="number-grid">${s.ids.map((id,i)=>`<button class="${i===reviewIndex?'current':''} ${Core.known(BYID.get(id))&&s.answers[id]?(Core.correct(BYID.get(id),s.answers[id])?'correct':'incorrect'):''}" data-review-jump="${i}" aria-label="${i+1}번 해설">${i+1}</button>`).join('')}</div></section>`;}
function guidePage(){const c=cfg(),customized=!!state.settings[state.exam];return `<div class="section-title"><div><div class="eyebrow">KNOW YOUR EXAM</div><h1>시험 안내</h1><p>일반 응시자의 필기시험 기준 · 공식 안내 확인일 ${CONFIG.verifiedAt}</p></div></div>${examTabs()}<section class="card"><h2>${c.name}</h2><p class="subtext">${state.exam==='health'?'8과목 필수, 과목당 20문항으로 총 160문항':'7과목 중 5과목 선택, 과목당 20문항으로 총 100문항'} · 객관식 4지선다</p>${customized?'<p class="note warning">사용자 설정을 적용 중입니다. 아래 공식 안내의 기본값과 구분해 이용해 주세요.</p>':''}<div class="table-wrap section-gap"><table><thead><tr><th>구분</th><th>과목</th><th>공식 시험시간</th><th>문항 수</th></tr></thead><tbody>${state.exam==='health'?`<tr><td>1교시</td><td>운동생리학 · 건강·체력평가<br>운동처방론 · 운동부하검사</td><td>10:00–11:20<br>80분</td><td>80</td></tr><tr><td>휴식</td><td>교시 간 휴식</td><td>11:20–11:40<br>20분</td><td>—</td></tr><tr><td>2교시</td><td>운동상해 · 기능해부학(운동역학 포함)<br>병태생리학 · 스포츠심리학</td><td>11:40–13:00<br>80분</td><td>80</td></tr>`:`<tr><td>선택 5과목</td><td>스포츠교육학 · 스포츠사회학 · 스포츠심리학<br>스포츠윤리 · 운동생리학 · 운동역학 · 한국체육사</td><td>10:00–11:40<br>100분</td><td>100</td></tr>`}</tbody></table></div><p class="note">필기 합격 기준: 모든 과목에서 100점 만점의 40점 이상, 전체 총점의 60% 이상.<br>모의고사에서는 정답 수를 백분율로 환산하여 적용합니다. 이 사이트의 결과는 공식 합격 판정이 아닙니다.</p><h3 class="section-gap">확인한 공식 출처</h3>${c.sources.map(s=>`<p class="subtext"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></p>`).join('')}<p class="details-note section-gap">공식 2026 시행 공고와 자격제도 안내를 대조했습니다. 향후 시험에 응시할 때는 해당 연도의 공식 공고를 확인해 주세요. 기출문제는 출제 당시의 기준을 반영하므로 현재 지침과 다를 수 있습니다.</p></section><section class="card section-gap"><h2>모의고사 설정</h2><p class="subtext">공식 구성이 바뀌거나 연습 조건을 바꾸고 싶다면 조정할 수 있습니다.</p><div class="settings-grid"><div class="field"><label for="set-count">과목당 문항 수</label><input id="set-count" type="number" min="1" max="100" value="${c.perSubject}"></div><div class="field"><label for="set-time1">${state.exam==='health'?'1교시':'시험'} 시간(분)</label><input id="set-time1" type="number" min="1" max="300" value="${c.minutes[0]}"></div>${state.exam==='health'?`<div class="field"><label for="set-time2">2교시 시간(분)</label><input id="set-time2" type="number" min="1" max="300" value="${c.minutes[1]}"></div><div class="field"><label for="set-break">휴식시간(분)</label><input id="set-break" type="number" min="0" max="60" value="${c.breakMinutes}"></div>`:''}<div class="field"><label for="set-subpass">과목별 기준(점)</label><input id="set-subpass" type="number" min="0" max="100" value="${c.passSubject}"></div><div class="field"><label for="set-totalpass">전체 기준(점)</label><input id="set-totalpass" type="number" min="0" max="100" value="${c.passTotal}"></div></div><div class="data-actions"><button class="btn" data-action="save-settings">설정 저장</button><button class="btn secondary" data-action="reset-settings">공식 기본값으로 복원</button></div><p class="helper">과목 선택 수는 공식 규정에 따라 고정됩니다. 설정 변경은 새로 시작하는 모의고사부터 적용됩니다.</p></section><section class="card section-gap"><h2>문제 자료 안내</h2>${difficultyGuide()}<p class="subtext">기출 ${nfmt(BANK.filter(q=>q.type==='공식 기출').length)}문항 + 학습용 창작 예시 ${nfmt(BANK.filter(q=>q.type==='창작 예상문제').length)}문항</p><details open><summary>첨부 원문과 정답표의 상태</summary><p>건강운동관리사 2018–2026년 1,440문항에는 첨부 최종 정답을 연결했습니다. 생활스포츠지도사 2급 2016–2026년 1,540문항 중 2018년 140문항은 정답표 미첨부로 채점되지 않습니다. 다른 생활스포츠지도사 정답은 본문에 최종 확정 근거가 없는 정답 가안으로 구분합니다. 정정 공지와 복수 인정 정답을 반영했습니다.</p></details><details><summary>기출문제의 해설과 원문 표시</summary><p>기출은 표·그림·수식을 보존한 원문 이미지입니다. 작성된 기출의 학습용 해설은 원문과 정답표를 바탕으로 AI가 작성했으며 공식 해설이 아닙니다. 해설에 정답 근거, 선택지별 설명, 핵심 개념과 참고 자료를 표시합니다. 판독이나 정답 해석이 불확실한 문항은 추가 검토 대상으로 구분합니다. 창작 예시는 기본 제공 과목마다 50문항이며, 모든 문항에 정답 근거와 선택지별 해설이 있습니다. 학습용으로 작성한 예상문제이며 실제 기출문제가 아닙니다. 원문 이미지는 화면 읽기 프로그램에 완전한 텍스트로 전달되지 않으며, 연결된 공통 지문은 앞선 문제와 함께 표시될 수 있습니다. ‘전체 페이지 확대’로 원문 문맥을 확인할 수 있습니다.</p></details><details><summary>이 브라우저에 저장되는 내용</summary><p>학습 기록·북마크·메모·진행 중인 학습은 이 브라우저의 localStorage에 저장됩니다. 로그인하면 계정에 기록을 동기화합니다. 로그인 전 기록은 계정 메뉴에서 직접 옮길 수 있습니다. 사이트 주소 변경, 시크릿 모드, 브라우저 데이터 삭제 시 기록이 사라질 수 있으므로 데이터 메뉴에서 기록을 백업하세요. 모의고사 시간은 창을 닫아도 흐르며, 연습 모드의 시간은 학습 화면이 보일 때만 누적됩니다.</p></details></section>`;}
function explanationCounts(){const official=BANK.filter(q=>q.type==='공식 기출');return {total:official.length,authored:official.filter(q=>q.explanation.kind==='authored').length,review:official.filter(q=>q.explanation.status==='needs_review').length};}
function dataPage(){const ec=explanationCounts();const official=BANK.filter(q=>q.type==='공식 기출').length,sample=BANK.filter(q=>q.type==='창작 예상문제').length;return `<div class="section-title"><div><div class="eyebrow">YOUR QUESTION LIBRARY</div><h1>문제 데이터</h1><p>문제를 추가하고, 소중한 학습 기록을 안전하게 보관하세요.</p></div></div><div class="two-cols"><section class="card"><span class="badge">현재 문제은행</span><div class="data-total">${nfmt(BANK.length)} <small>문항</small></div><p class="subtext">공식 기출 ${nfmt(official)} · 창작 예시 ${nfmt(sample)}<br>추가로 불러온 문제 ${nfmt(custom.questions.length)}</p><p class="note">${Object.entries(Core.difficultyCounts(BANK)).map(([level,count])=>`난이도 ${level} ${nfmt(count)}문항`).join(' · ')}<br>내용 기준 예상 난이도이며 공식 등급이나 이용자 정답률이 아닙니다.</p><p class="note">기출 해설 작성 ${nfmt(ec.authored)} / ${nfmt(ec.total)}문항<br>추가 검토 ${nfmt(ec.review)}문항 · 아직 미작성 ${nfmt(ec.total-ec.authored)}문항</p><div class="data-actions"><button class="btn" data-action="export-questions" ${exportBusy?'disabled':''}>${exportBusy?'이미지 준비 중…':'문제 JSON 내보내기'}</button><button class="btn secondary" data-action="import-questions">문제 불러오기</button></div><p class="helper">문제 JSON 내보내기는 모든 해설과 원문 이미지를 내려받습니다. 인터넷 연결이 필요하며 시간이 걸릴 수 있습니다. 불러온 문제는 기존 문제에 추가되며 중복 ID는 허용하지 않습니다.</p><div id="import-feedback" class="import-feedback" aria-live="polite"></div></section><section class="card"><span class="badge">나만의 학습 기록</span><h2 class="section-gap">기록을 이어가세요.</h2><p class="subtext">두 시험의 학습 기록, 오답, 북마크, 메모를 하나의 파일로 저장합니다.</p><div class="data-actions"><button class="btn secondary" data-action="backup">학습 기록 백업</button><button class="btn secondary" data-action="restore">학습 기록 복원</button></div><p class="helper">기존 오프라인 파일에서 백업한 학습 기록도 여기에서 복원할 수 있습니다. 사이트와 오프라인 파일의 기록은 자동으로 합쳐지지 않습니다. 기록 백업은 문제 데이터와 별도입니다. 직접 추가한 문제가 있다면 문제 JSON도 함께 보관해 주세요.</p></section></div><section class="card section-gap"><h2>문제 추가 방법</h2><p class="subtext">아래 형식의 JSON 파일을 만든 뒤 ‘문제 불러오기’를 누르세요. 정답 번호는 1부터 4까지입니다.</p><div class="data-actions"><button class="btn secondary" data-action="template">예시 JSON 내려받기</button></div><pre class="code-example">${esc(JSON.stringify({questions:[{id:'my-health-001',exam:'health',subject:'운동생리학',unit:'에너지 대사',difficulty:'하',type:'창작 예상문제',year:null,number:1,stem:'산화적 인산화의 주된 장소는?',choices:['리보솜','미토콘드리아','골지체','리소솜'],answer:[2],explanation:{summary:'미토콘드리아 내막에서 산화적 인산화가 이루어진다.',choices:['단백질 합성과 관련된다.','정답: 전자전달계가 위치한다.','물질의 가공과 분류에 관여한다.','세포 내 분해에 관여한다.']},source:{file:'자체 제작',status:'created',note:'학습용 창작 예상문제이며 실제 기출문제가 아닙니다'}}]},null,2))}</pre><p class="note">exam: 건강운동관리사 = health, 생활스포츠지도사 2급 = sports<br>answer: [2]처럼 입력합니다. 복수 인정 정답은 [1, 3], 정답 미확인 기출은 null입니다.<br>difficulty: 하 / 중 / 상 (미평가 문제는 미분류)<br>기존 기초·중급·응용 값은 가져올 때 하·중·상으로 변환하며, 알 수 없는 기존 값은 미분류로 보관합니다.<br>출처 상태: final(최종), preliminary(가안), missing(미확인), created(창작)</p><p class="helper">필수 필드·선택지 개수·정답 범위·시험별 과목명·중복 ID를 검사합니다. 원문 이미지를 포함하는 데이터는 내보내기 파일의 pages와 crop 형식을 그대로 사용하세요. 자료가 브라우저 저장 한도를 넘으면 추가되지 않으며 안내가 표시됩니다.</p></section>`;}
function download(name,data){const b=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
let exportBusy=false;
async function exportQuestions(){
 if(exportBusy)return;
 exportBusy=true;
 const snapshot=structuredClone(BANK),assets={...ASSETS};
 const update=message=>{document.querySelectorAll('[data-action="export-questions"]').forEach(b=>{b.disabled=exportBusy;b.textContent=message;});};
 update('이미지 준비 중…');
 toast('전체 해설과 원문 이미지를 내려받습니다. 완료될 때까지 이 페이지를 열어 두세요.');
 try{
  const questions=await ExplanationLibrary.materialize(snapshot);
  const pages=await WebFiles.exportPages(questions,assets,(done,total)=>update(`이미지 준비 중 ${done} / ${total}`));
  download('트레이너_자격증_문제_은행집_문제.json',{schemaVersion:1,questions,pages});
  toast('문제와 해설과 원문 이미지를 포함한 JSON 파일을 저장했습니다.');
 }catch(e){toast('문제 내보내기에 실패했습니다. 인터넷 연결을 확인하고 다시 시도해 주세요.');}
 finally{exportBusy=false;update('문제 JSON 내보내기');}
}

async function importQuestions(file){if(!file)return;const feedback=$('#import-feedback');try{if(file.size>250*1024*1024)throw Error('250MB 이하의 JSON 파일을 선택해 주세요.');const parsed=JSON.parse(await file.text()),data=Core.validateImport(parsed,BANK,CONFIG,await WebFiles.validationAssets(parsed,ASSETS)),next={questions:[...custom.questions,...data.questions],pages:{...custom.pages,...data.pages}};try{localStorage.setItem(CUSTOM,JSON.stringify(next));}catch(e){throw Error('브라우저 저장 공간이 부족하여 추가하지 않았습니다. 이미지 크기나 문제 수를 줄여 다시 시도해 주세요.');}custom=next;BANK=[...BUILTIN,...custom.questions];Object.assign(ASSETS,data.pages);BYID=new Map(BANK.map(q=>[q.id,q]));render();$('#import-feedback').innerHTML=`<p class="note success">✓ ${data.questions.length}문항을 추가하고 저장했습니다.</p>`;}catch(e){const f=$('#import-feedback')||feedback;if(f){f.textContent=`불러오지 못했습니다. 기존 문제는 변경되지 않았습니다.\n${e instanceof SyntaxError?'JSON 문법을 확인해 주세요. 쉼표·따옴표·괄호가 올바르지 않습니다.':e.message}`;f.className='import-feedback note warning';}else toast(e.message);}$('#import-file').value='';}
function validateBackup(obj){if(!obj||obj.kind!=='motionnote-backup'||obj.version!==1)throw Error('트레이너 자격증 문제 은행집 학습 기록 백업 파일이 아닙니다.');const x=obj.state;if(!x||!x.records||typeof x.records!=='object'||Array.isArray(x.records)||!Array.isArray(x.bookmarks)||!Array.isArray(x.history)||!x.notes||typeof x.notes!=='object')throw Error('기록 형식이 올바르지 않습니다.');for(const [id,r] of Object.entries(x.records)){if(!BYID.has(id))throw Error(`문제 ${id}가 없습니다. 문제 JSON을 먼저 불러와 주세요.`);if(!r||r.exam!==BYID.get(id).exam||r.subject!==BYID.get(id).subject||!['attempts','correct','wrong'].every(k=>Number.isSafeInteger(r[k])&&r[k]>=0)||r.attempts!==r.correct+r.wrong||typeof r.resolved!=='boolean')throw Error('풀이 기록의 수치가 올바르지 않습니다.');}if(x.bookmarks.some(id=>typeof id!=='string'||!BYID.has(id))||Object.entries(x.notes).some(([id,n])=>!BYID.has(id)||typeof n!=='string'||n.length>10000))throw Error('북마크 또는 메모 형식이 올바르지 않습니다.');for(const h of x.history){if(!h||!Array.isArray(h.ids)||!h.ids.length||h.ids.some(id=>!BYID.has(id)||BYID.get(id).exam!==h.exam)||!h.answers||typeof h.answers!=='object'||!['health','sports'].includes(h.exam)||typeof h.id!=='string'||typeof h.label!=='string'||!Number.isFinite(h.finishedAt)||!Number.isFinite(h.elapsedMs)||h.elapsedMs<0||Object.values(h.answers).some(v=>!Number.isInteger(v)||v<1||v>4))throw Error('학습 내역의 형식이 올바르지 않습니다.');if(h.rules){const r=h.rules;if(!Number.isInteger(r.perSubject)||r.perSubject<1||r.perSubject>100||!Array.isArray(r.minutes)||r.minutes.length!==(h.exam==='health'?2:1)||r.minutes.some(n=>!Number.isInteger(n)||n<1||n>300)||!['passSubject','passTotal'].every(k=>Number.isInteger(r[k])&&r[k]>=0&&r[k]<=100)||!Number.isInteger(r.breakMinutes)||r.breakMinutes<0||r.breakMinutes>60)throw Error('백업의 시험 설정이 올바르지 않습니다.');h.rules={...CONFIG[h.exam],perSubject:r.perSubject,minutes:r.minutes,passSubject:r.passSubject,passTotal:r.passTotal,breakMinutes:r.breakMinutes};}h.full=h.full===true;h.summary=Core.summarize(h.ids.map(id=>BYID.get(id)),h.answers);}
 return {...defaultState(),exam:['health','sports'].includes(x.exam)?x.exam:'health',records:x.records,bookmarks:[...new Set(x.bookmarks)],notes:x.notes,history:x.history,settings:state.settings,session:null};}
async function restoreBackup(file){if(!file)return;try{const x=validateBackup(JSON.parse(await file.text()));if(!await modal('학습 기록을 복원할까요?','로그인 중에는 개인 이력으로 병합하며 기존 계정 자료를 덮어쓰지 않습니다. 로그인 전에는 현재 두 시험의 기록을 백업 내용으로 바꿉니다. 진행 중인 학습은 종료됩니다. 시험 설정은 유지됩니다.','기록 복원'))return;if(window.TrainerCloud?.loggedIn()){await TrainerCloud.importState(x);toast('개인 학습 이력으로 가져왔습니다. 서버 저장 상태를 확인하세요.');return;}state=x;save();form.subjects=[CONFIG[state.exam].subjects[0]];view='history';render();toast('학습 기록을 복원했습니다.');}catch(e){toast(e instanceof SyntaxError?'올바른 JSON 백업 파일이 아닙니다.':e.message);}$('#restore-file').value='';}
function saveSettings(){if(state.session){toast('진행 중인 학습을 완료한 뒤 설정을 바꿔 주세요.');return;}const read=(id,min,max)=>{const x=Number($(id).value);if(!Number.isInteger(x)||x<min||x>max)throw Error(`${$(id).previousElementSibling.textContent} 값을 ${min}~${max} 사이 정수로 입력하세요.`);return x;};try{const minutes=[read('#set-time1',1,300)];if(state.exam==='health')minutes.push(read('#set-time2',1,300));state.settings[state.exam]={perSubject:read('#set-count',1,100),minutes,breakMinutes:state.exam==='health'?read('#set-break',0,60):0,passSubject:read('#set-subpass',0,100),passTotal:read('#set-totalpass',0,100)};save();render();toast('새 모의고사에 적용할 설정을 저장했습니다.');}catch(e){toast(e.message);}}
async function resetExam(){if(!await modal('이 시험의 기록을 초기화할까요?',`${CONFIG[state.exam].name}의 풀이 기록, 오답, 북마크, 메모가 삭제됩니다. 먼저 백업해 두는 것을 권장합니다. 다른 시험의 기록은 유지됩니다.`,'초기화'))return;try{await window.TrainerCloud?.reset(state.exam);}catch(e){toast(e.message);return;}const ids=new Set(BANK.filter(q=>q.exam===state.exam).map(q=>q.id));for(const id of ids){delete state.records[id];delete state.notes[id];}state.bookmarks=state.bookmarks.filter(id=>!ids.has(id));state.history=state.history.filter(h=>h.exam!==state.exam);if(state.session?.exam===state.exam)state.session=null;save();render();toast('선택한 시험의 기록을 초기화했습니다.');}
async function action(a){const s=state.session;switch(a){case 'retry-explanation':{const q=view==='review'?BYID.get(reviewSession.ids[reviewIndex]):BYID.get(s.ids[s.index]);ExplanationLibrary.retry(q);render();break;}case 'retry-image':render();break;case 'zoom-in':case 'zoom-out':state.preferences.zoom=Math.max(100,Math.min(250,(state.preferences.zoom||100)+(a==='zoom-in'?25:-25)));save();if($('#question-canvas'))$('#question-canvas').style.width=state.preferences.zoom+'%';if($('#zoom-value'))$('#zoom-value').textContent=state.preferences.zoom+'%';break;case 'start':startFromForm();break;case 'resume':state.exam=s.exam;view='study';s.lastTick=Date.now();render();tick();break;case 'select-all':if(form.mode==='mock'){if(state.exam==='sports')form.subjects=[];}else form.subjects=form.subjects.length===cfg().subjects.length?[]:cfg().subjects.slice();render();break;case 'check':checkAnswer();break;case 'prev':jump(s.index-1);break;case 'next':jump(s.index+1);break;case 'flag':{const id=s.ids[s.index],i=s.flags.indexOf(id);if(i<0)s.flags.push(id);else s.flags.splice(i,1);save();render();break;}case 'submit':await submit();break;case 'skip-break':nextPhase();break;case 'review-collection':begin(collectionIds(),'review',(view==='wrong'?'오답 복습':'북마크 복습')+(listDifficulty==='all'?'':' · 난이도 '+listDifficulty));break;case 'review-result':reviewOrigin='result';reviewSession=currentResult();reviewIndex=0;view='review';render();window.scrollTo(0,0);break;case 'back-result':if(reviewOrigin==='wrong')returnWrong();else{view='result';render();}break;case 'retry-wrong':{const h=currentResult();state.exam=h.exam;begin(HistoryCore.wrongIds(h,BYID),'review','오답 복습');break;}case 'export-questions':exportQuestions();break;case 'import-questions':$('#import-file').click();break;case 'backup':flushTime();download('트레이너_자격증_문제_은행집_학습기록_백업.json',{kind:'motionnote-backup',version:1,savedAt:new Date().toISOString(),state});break;case 'restore':$('#restore-file').click();break;case 'template':{const q=structuredClone(BUILTIN.find(q=>q.type==='창작 예상문제'));q.id='my-health-001';download('트레이너_자격증_문제_은행집_문제_양식.json',{questions:[q]});break;}case 'save-settings':saveSettings();break;case 'reset-settings':if(state.session){toast('진행 중인 학습을 먼저 완료해 주세요.');break;}delete state.settings[state.exam];save();render();toast('공식 기본값으로 복원했습니다.');break;case 'reset-exam':await resetExam();break;}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b||b.disabled)return;if(b.dataset.difficulty){if(form.mode==='mock')return;form.difficulty=b.dataset.difficulty;state.preferences??={};state.preferences.practiceDifficulty??={};state.preferences.practiceDifficulty[state.exam]=form.difficulty;save();render();$$('[data-difficulty]').find(el=>el.dataset.difficulty===form.difficulty)?.focus();return;}if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.exam){switchExam(b.dataset.exam);return;}if(b.dataset.mode){form.mode=b.dataset.mode;if(form.mode==='subject')form.subjects=[form.subjects[0]||cfg().subjects[0]];else if(form.mode==='mock'){form.subjects=cfg().subjects.slice(0,cfg().selectCount);form.year=form.type==='sample'?'all':String(cfg().years[0]);}render();return;}if(b.dataset.action){action(b.dataset.action);return;}if(b.dataset.choice){choose(Number(b.dataset.choice));return;}if(b.dataset.jump!==undefined){jump(Number(b.dataset.jump));return;}if(b.dataset.bookmark){toggleBookmark(b.dataset.bookmark);return;}if(b.dataset.result){historyId=b.dataset.result;view='result';render();window.scrollTo(0,0);return;}if(b.dataset.reviewJump!==undefined){reviewIndex=Number(b.dataset.reviewJump);render();window.scrollTo(0,0);return;}if(b.dataset.practiceId){begin([b.dataset.practiceId],'review','문제 다시 풀기');return;}if(b.dataset.page){listPage=Number(b.dataset.page);render();window.scrollTo(0,0);return;}if(b.dataset.original){const d=$('#dialog');d.className='image-dialog';$('#dialog-content').innerHTML=`<div class="card-head"><h2>원문 전체 페이지</h2><button class="btn secondary" data-dialog="cancel">닫기 ✕</button></div><p class="helper">현재 문제 번호를 확인하세요. 원문 확대를 위해 브라우저 확대 기능을 사용할 수 있습니다.</p><img src="${ASSETS[b.dataset.original]}" alt="기출문제 원문 전체 페이지">`;d.showModal();return;}if(b.classList.contains('brand')){e.preventDefault();navigate('home');}});
document.addEventListener('change',e=>{const el=e.target;if(el.name==='subject'){if(form.mode==='subject')form.subjects=[el.value];else if(el.checked){if(form.mode==='mock'&&state.exam==='sports'&&form.subjects.length>=5){el.checked=false;toast('모의고사는 5과목까지 선택할 수 있습니다. 다른 과목을 먼저 해제해 주세요.');return;}form.subjects.push(el.value);}else form.subjects=form.subjects.filter(s=>s!==el.value);updateSelection();}if(el.id==='year'){form.year=el.value;render();}if(el.id==='qtype'){form.type=el.value;if(form.type==='sample')form.year='all';render();}if(el.id==='count'){form.count=Number(el.value);updateSelection();}if(el.id==='list-difficulty'){listDifficulty=el.value;listPage=1;render();$('#list-difficulty')?.focus();}if(el.id==='list-filter'){listFilter=el.value;listPage=1;render();}if(el.id==='import-file')importQuestions(el.files[0]);if(el.id==='restore-file')restoreBackup(el.files[0]);});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value.slice(0,10000);clearTimeout(saveTimer);saveTimer=setTimeout(()=>{save();if($('#note-save-status'))$('#note-save-status').textContent=window.TrainerCloud?.loggedIn()?'기기에 임시 저장 · 전송 상태는 상단 확인':'기기에 저장됨';},350);}if(el.id==='list-search'){listSearch=el.value;listPage=1;const pos=el.selectionStart;render();const input=$('#list-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if($('#dialog').open||$('#account-dialog')?.open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(view==='study'&&state.session?.stage==='quiz'){if(/^[1-4]$/.test(e.key)){e.preventDefault();choose(Number(e.key));}else if(e.key==='ArrowRight'){e.preventDefault();jump(state.session.index+1);}else if(e.key==='ArrowLeft'){e.preventDefault();jump(state.session.index-1);}else if(e.key.toLowerCase()==='b'){e.preventDefault();toggleBookmark(state.session.ids[state.session.index]);}}});
let tickCounter=0;
function tick(){if(cloudAction)return;const s=state.session;if(!s)return;flushTime();const now=Date.now();if(s.mode==='mock'&&s.stage==='quiz'&&now>=s.deadline){if($('#dialog').open){$('#dialog').close();dialogResolve?.(false);dialogResolve=null;}submit(true);return;}if(s.stage==='break'&&now>=s.breakDeadline){nextPhase();return;}if(view==='study'){if($('#session-timer'))$('#session-timer').textContent=time(s.mode==='mock'?s.deadline-now:elapsed(s));if($('#break-timer'))$('#break-timer').textContent=time(s.breakDeadline-now);}if(++tickCounter%10===0)save();}
setInterval(tick,1000);window.addEventListener('pagehide',()=>{flushTime();save();});document.addEventListener('visibilitychange',()=>{if(state.session){state.session.lastTick=Date.now();save();if(!document.hidden)tick();}});
document.addEventListener('explanations-loaded',()=>{if(view==='review'||view==='study'&&state.session?.mode!=='mock'&&state.session?.checked[state.session.ids[state.session.index]])render();});
render();

window.TrainerCloud?.attach({
 read:()=>state,
 apply:(next,accountChanged=false)=>{const previous=state.session?.id;state={...defaultState(),...next};if(!CONFIG[state.exam])state.exam='health';if(accountChanged){resetWrongFilters();resetHistoryFilters();reviewOrigin='result';cloudAction=false;document.querySelector('.cloud-lock')?.remove();}if(accountChanged||(view==='study'&&(!state.session||previous!==state.session.id))){view='home';historyId=null;reviewSession=null;}form.subjects=form.subjects.filter(sub=>CONFIG[state.exam].subjects.includes(sub));if(!form.subjects.length)form.subjects=[CONFIG[state.exam].subjects[0]];render();},
 timer:s=>{if(state.session?.id===s.id){for(const k of ['deadline','phaseStartedAt','breakDeadline'])if(s[k]!==undefined)state.session[k]=s[k];}},
 resume:s=>{state.session=s;state.exam=s.exam;view='study';render();tick();},
 lock:message=>{if(document.querySelector('.cloud-lock'))return;cloudAction=true;const el=document.createElement('div');el.className='cloud-lock';el.innerHTML=`<div><h2>최신 기록을 불러와 주세요</h2><p>${esc(message)}</p><button class="btn" onclick="location.reload()">새로고침</button></div>`;document.body.append(el);}
});
